/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null; right = null; }
 * }
 **/

class Solution {
    public TreeNode deleteNode(TreeNode root, int key) {
        TreeNode parent = null;
        TreeNode current = root;

        while (current != null && current.data != key) {
            parent = current;
            if (key < current.data) {
                current = current.left;
            } else {
                current = current.right;
            }
        }

        if (current == null) {
            return root;
        }

        TreeNode replacement = joinSubtrees(current);

        if (parent == null) {
            return replacement;
        }

        if (parent.left == current) {
            parent.left = replacement;
        } else {
            parent.right = replacement;
        }

        return root;
    }

    private TreeNode joinSubtrees(TreeNode node) {
        if (node.left == null) {
            return node.right;
        }
        if (node.right == null) {
            return node.left;
        }

        TreeNode rightmost = node.left;
        while (rightmost.right != null) {
            rightmost = rightmost.right;
        }
        rightmost.right = node.right;
        return node.left;
    }
}
```

The empty tree and a missing key both leave the tree unchanged. This code changes child links directly and uses no recursion.

Time complexity: O(h).
Space complexity: O(1), apart from a few node references.

