class Solution {
    public TreeNode mergeChilds(TreeNode root) {
           TreeNode left = root.left;
           TreeNode right = root.right;
           root.left = null;
           root.right = null;
           if (left==null || right==null) return left!=null ? left : right;
           else {
                TreeNode edge = left;
                while(edge.right!=null)
                    edge = edge.right;
                edge.right = right; 
            return left; 
           }
    }
    public TreeNode delete(TreeNode root, TreeNode parent) {
        //#1
        if(parent == null) { 
          return mergeChilds(root);
        } 
        //#2
        else if(root.left==null && root.right==null) {
            if(parent.left == root) 
